/**
 * DEP-4 PII / credential filter — cross-language parity (TypeScript / WASM side).
 *
 * Loads `corpus.json` (next to this file, generated by `generate_corpus.py`)
 * and asserts that the WASM `piiFilter` returns exactly each item's expected
 * decision + category. The Rust runner
 * (`rust/totalreclaw-core/tests/pii_corpus.rs`) and the PyO3 runner
 * (`python/tests/test_pii_parity.py`) assert the same expectations, so the
 * three runtimes agree item-for-item. Failure lines print ids + decisions
 * only, never corpus text.
 *
 * Run (build the flat WASM pkg first):
 *   cd rust/totalreclaw-core && wasm-pack build --target nodejs --out-dir pkg --features wasm
 *   cd tests/parity && npx tsx pii/pii-parity.test.ts
 */

import { readFileSync } from 'fs';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

const __dirname = dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);

const wasmPath = resolve(__dirname, '..', '..', '..', 'rust', 'totalreclaw-core', 'pkg', 'totalreclaw_core.js');
const wasm = require(wasmPath) as { piiFilter: (text: string) => string };

interface CorpusItem {
  id: string;
  set: 'negative' | 'positive';
  expect: 'allow' | 'block' | 'flag';
  category?: string;
  text: string;
}

interface Decision {
  decision: string;
  category?: string;
  message?: string;
}

const corpus = JSON.parse(readFileSync(resolve(__dirname, 'corpus.json'), 'utf8')) as { items: CorpusItem[] };
const failures: string[] = [];
const messageByCategory = new Map<string, string>();

for (const item of corpus.items) {
  const out = JSON.parse(wasm.piiFilter(item.text)) as Decision;
  if (out.decision !== item.expect || out.category !== item.category) {
    failures.push(`${item.id}: expected ${item.expect}/${item.category ?? '-'}, got ${out.decision}/${out.category ?? '-'}`);
    continue;
  }
  if (out.decision === 'allow') {
    if (Object.keys(out).length !== 1) failures.push(`${item.id}: allow must carry only "decision"`);
    continue;
  }
  if (typeof out.message !== 'string' || !out.message.startsWith('Not saved: ')) {
    failures.push(`${item.id}: ${out.decision} must carry the core message`);
    continue;
  }
  const seen = messageByCategory.get(out.category as string);
  if (seen !== undefined && seen !== out.message) failures.push(`${item.id}: message for ${out.category} is not stable`);
  messageByCategory.set(out.category as string, out.message);
}

// Byte-level wire shape (key order is part of the cross-client contract).
const allowRaw = wasm.piiFilter('my doctor is Dr. X');
if (allowRaw !== '{"decision":"allow"}') failures.push(`allow wire shape: ${allowRaw}`);
const blockRaw = wasm.piiFilter('card 4111 1111 1111 1111');
if (!blockRaw.startsWith('{"decision":"block","category":"payment_card","message":"Not saved: ')) {
  failures.push('block wire shape: unexpected key order or category');
}

if (failures.length > 0) {
  console.error(`PII parity (WASM): ${failures.length} failure(s)`);
  for (const f of failures) console.error(`  ${f}`);
  process.exit(1);
}
console.log(`PII parity (WASM): all ${corpus.items.length} corpus items match`);
